  function setLocation(title,subtitle,weather=true){$('location').innerHTML=(state.route!=='home'&&state.route!=='welcome'?'<button class="back-link" data-action="go:home">'+icon('back')+' 回我的小屋</button>':'')+'<h1>'+title+'</h1><p>'+subtitle+'</p>'+(weather?'<span class="weather-pill">'+icon(state.night?'moon':'sun')+(state.night?'月亮值班中 · 夜晚':'云朵轻轻，今天是晴天')+'</span>':'');}
