  function dealSelection(date){
    const ids=dealMetadata.map(def=>def.id).sort();let seed=2166136261;for(const character of 'cottage-deals-v1:'+date)seed=Math.imul(seed^character.charCodeAt(0),16777619)>>>0;if(!seed)seed=0x6d2b79f5;
    const random=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296;};
    for(let i=0;i<Math.min(6,ids.length);i++){const j=i+Math.floor(random()*(ids.length-i));[ids[i],ids[j]]=[ids[j],ids[i]];}return ids.slice(0,6).map(id=>dealMetadataById[id]);
  }
  function dealValidDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const parts=value.split('-').map(Number),date=new Date(0);date.setFullYear(parts[0],parts[1]-1,parts[2]);date.setHours(12,0,0,0);return parts[0]>=1&&date.getFullYear()===parts[0]&&date.getMonth()===parts[1]-1&&date.getDate()===parts[2];}
