  const questFocusHandled=new WeakSet();
  function questPageState(){if(!state.questDemo)state.questDemo={mode:'progress',samples:{},chapter:2,category:'baker',milestoneId:null,story:null,lastAction:null};const d=state.questDemo;if(!d.samples[d.mode])d.samples[d.mode]=questMakeSample(d.mode);return d;}
  function questMakeSample(mode){
    const final=mode==='final',claims=questMetadata.main.slice(0,final?34:10).map(q=>q.id),pieces=questMetadata.main.filter(q=>claims.includes(q.id)&&q.rainbow).map(q=>q.rainbow),date=mode==='future'?'2026-10-31':questMetadata.date,dailyIds=mode==='future'?questMetadata.dailyFuture:questMetadata.dailyToday;
    return {mainClaims:claims,rainbow:pieces,achievementClaims:['builder_1','collector_1','friend_1','baker_1','baker_2','gardener_1','gamer_1','fashion_1','photographer_1'],milestones:[],storySeen:[],endingSeen:false,metrics:{named:1,bedroom:1,bed:1,lily:1,pudding:1,orange:1,bakeryPlays:1,kitchen:1,bedroomStars:3,wallpaperChanges:1,floors:final?4:2,harvests:mode==='ready'?3:1,wishesDone:0,roomCount:4,collection:35,residentCount:final?12:6,room_living:1,maxAffection:120,bakeryOrders:15,minigamePlays:8,outfitsOwned:14,photos:3},dailyDate:date,daily:dailyIds.map((id,i)=>{const def=questMetadata.daily.find(q=>q.id===id);return {id,progress:mode==='ready'||mode==='future'?def.target:i===0?def.target:i===1?Math.max(0,def.target-1):0,claimed:false};}),chestClaimed:false,wallet:{coin:12480,heart:286,exp:0},items:{},outfits:{},badges:[],lastReward:''};
  }
  function questStore(){const d=questPageState();return d.samples[d.mode];}
  function questCurrentIndex(s=questStore()){const n=questMetadata.main.findIndex(q=>!s.mainClaims.includes(q.id));return n<0?35:n;}
  function questAvailableChapter(){return questMetadata.main[questCurrentIndex()]?.chapter||5;}
  function questProgress(def,claimed,s=questStore()){
    const conditions=(def.conditions||[{metric:def.metric,target:def.target,label:def.description}]).map(c=>{const metric=c.metric==='rainbowCount'?s.rainbow.length:s.metrics[c.metric]||0,value=claimed?c.target:Math.min(c.target,Math.max(0,metric));return {...c,progress:value,done:value>=c.target};});return {conditions,done:conditions.every(c=>c.done),progress:def.conditions?conditions.filter(c=>c.done).length:conditions[0].progress,target:def.conditions?conditions.length:def.target};
  }
  function questMainEntries(){const s=questStore(),next=questCurrentIndex(s);return questMetadata.main.map((q,index)=>{const claimed=s.mainClaims.includes(q.id);return {...q,...questProgress(q,claimed,s),claimed,locked:!claimed&&index!==next};});}
  function questAchievementEntries(category){const s=questStore();return questMetadata.achievements.filter(q=>!category||q.category===category).map(q=>{const claimed=s.achievementClaims.includes(q.id),locked=questMetadata.achievements.some(previous=>previous.category===q.category&&previous.tier<q.tier&&!s.achievementClaims.includes(previous.id));return {...q,...questProgress(q,claimed,s),claimed,locked};});}
  function questRewardText(reward){return [reward.coin?reward.coin+'糖果':'',reward.exp?reward.exp+'经验':'',reward.heart?reward.heart+'爱心':'',reward.itemId?questMetadata.itemNames[reward.itemId]+' ×1':'',reward.outfitId?questMetadata.outfitNames[reward.outfitId]:''].filter(Boolean).join(' · ');}
  function questRewardFits(rewards){const s=questStore(),items={};let coin=s.wallet.coin,heart=s.wallet.heart;for(const reward of rewards){coin+=reward.coin||0;heart+=reward.heart||0;if(reward.itemId)items[reward.itemId]=(items[reward.itemId]||0)+1;}return coin<=1000000000&&heart<=1000000000&&Object.keys(items).every(id=>(s.items[id]||0)+items[id]<=9999);}
