    if(clockBehind)reason='示例本地日期早于领取记录，等日期晚于上次记录后，再收下一份。';else if(claimedToday)reason='今天的心意已经收好。下个可领取日期继续下一份，漏领不清零。';else if(saved.claimed>=C.maxClaims)reason='心意记录已到10亿次上限，不能继续新增领取。';else if(reward.kind==='coin'&&s.coin+reward.coin>C.maxCoin)reason='糖果罐容量不足，先用掉一些，再收这一份。';else if(reward.kind==='seeds'&&Object.keys(C.seeds).some(id=>(s.seeds[id]||0)+C.seeds[id]>C.maxStock))reason='种子袋容量不足，先种下一些；整包种子和领取资格都会保留。';else if(reward.kind==='furniture'&&(!reward.itemId||(s.inventory[reward.itemId]||0)>=C.maxStock))reason='这件同款家具的库存已满，先腾出一格；不会换奖或换糖果。';let completed=saved.claimed%7;if((claimedToday||clockBehind)&&saved.claimed>0&&completed===0)completed=7;
    return {date:s.date,day,reward,claimed:saved.claimed,lastClaimDate:saved.lastClaimDate,lastReward:saved.lastReward,claimedToday,clockBehind,completed,cycle:Math.floor((saved.claimed-(completed===7?1:0))/7)+1,canClaim:!d.busy&&!reason,reason};
