  // 第十五批：收礼后的生日舞台只展示；不处理共享日历、年度领取或任何保存。
  const birthdayDefinition={"title":"朋友来庆生","greeting":"今天，把最甜的一小块时光留给你。","quiet":"小曲由小屋在本机奏响；静音也能看祝福、一起庆生。","empty":"糯米先陪你许个愿，朋友搬来后，也会加入今天的庆祝。","closing":"今天的生日礼物已经收好；再庆祝只重看表演，不重复送礼。","nuomi":"生日快乐！愿你慢慢长大，也一直保留喜欢小小事物的心。","blessings":{"lily":"生日快乐！给你留了蛋糕上最甜的那颗草莓。","pudding":"森林的风也来送祝福啦，愿你每天都吃得香、睡得暖。","orange":"我想把今天画成一张画，名字就叫「你笑起来的样子」。","mianmian":"送你一条看不见的小围巾，开心和难过时都暖暖地围着你。","bobo":"生日快乐！今天的快乐可以跳得高一点，再高一点！","xingxing":"这首小曲送给你，愿你的每个愿望都有温柔的回音。","lizi":"我收集了十二颗亮晶晶的好心情，今天把它们都送给你。","yuanyuan":"今天慢慢许愿、慢慢吃蛋糕，我们会陪你把快乐过久一点。","mimi":"我把最软的星星枕头借给你，今晚要做一个特别甜的梦。","doudou":"为你转一圈、拍两下手！愿新的一岁有好多想试试的事。","shirley":"请收下这份轻轻的祝福，愿你每天都能按照自己的节拍跳舞。","rainbow":"我有一点点害羞，但还是想大声说：有你在，真好。生日快乐！"}};
  const birthdayAuditModes=[['ready','生日当天 · 年度礼物已收 · 4位朋友'],['none','生日当天 · 0位入住朋友'],['many','生日当天 · 12位入住朋友'],['handoff','收礼后交接入场 · fromClaim不叠曲'],['not-today','非生日当天 · 禁止进入'],['unclaimed','生日当天但未收年度礼物 · 禁止进入'],['reduced','减少动态 · 静态舞台']];
  let activeBirthday=null,birthdaySerial=0;
  function birthdayMakeSample(mode){return{date:mode==='not-today'?'2026-10-31':'2026-10-30',profile:{name:'小棉花',birthday:'10-30'},claimed:mode!=='unclaimed',residents:Object.fromEntries(residentProfiles.map(p=>[p.id,{movedIn:mode==='none'?false:mode==='many'||['lily','pudding','orange','bobo'].includes(p.id)}])),fromClaim:mode==='handoff',reduced:mode==='reduced',version:0,openCount:0,songRequests:0,notice:''};}
  function birthdayPageState(){if(!state.birthdayDemo)state.birthdayDemo={mode:'ready',samples:{}};const p=state.birthdayDemo;if(!p.samples[p.mode])p.samples[p.mode]=birthdayMakeSample(p.mode);return p;}
  function birthdayStore(){const p=birthdayPageState();return p.samples[p.mode];}
  function birthdayAvailable(d=birthdayStore()){return d.date.slice(5)===d.profile.birthday&&d.claimed;}
  function birthdayGuests(d=birthdayStore()){return residentProfiles.filter(def=>d.residents[def.id]?.movedIn).map(def=>def.id);}
  function birthdayNuomi(){return '<span class="bp-nuomi" aria-hidden="true"><svg viewBox="0 0 100 100"><defs><linearGradient id="bp-nuomi-clay" x2=".7" y2="1"><stop stop-color="#fffdf1"/><stop offset="1" stop-color="#deded1"/></linearGradient></defs><ellipse cx="50" cy="89" rx="29" ry="5" fill="#9e9c7e" opacity=".16"/><path d="M22 77C1 67 9 41 28 41 21 14 65 10 70 34 96 30 107 68 82 78 64 89 38 87 22 77Z" fill="url(#bp-nuomi-clay)"/><ellipse cx="36" cy="57" rx="3" ry="4" fill="#5b7354"/><ellipse cx="65" cy="57" rx="3" ry="4" fill="#5b7354"/><ellipse cx="26" cy="66" rx="7" ry="4" fill="#ebc3be"/><ellipse cx="75" cy="66" rx="7" ry="4" fill="#ebc3be"/><path d="M44 68q7 7 14 0" fill="none" stroke="#819377" stroke-width="2" stroke-linecap="round"/></svg></span>';}
