  function birthdayFigure(id){return '<div class="bp-resident" data-birthday-guest="'+id+'">'+residentPortrait(residentProfile(id),true)+'<span>'+esc(residentProfile(id).name)+'</span></div>';}
  function birthdayTheatre(ids,name,preset,compact=false){const half=Math.ceil(ids.length/2);return '<div class="bp-theatre '+(compact?'compact':'')+' '+(ids.length>4?'many':'')+'" role="img" aria-label="'+esc(name+'戴着生日皇冠，和'+(ids.length?ids.map(id=>residentProfile(id).name).join('、'):'糯米')+'围着生日蛋糕庆祝')+'"><div class="bp-bunting" aria-hidden="true">'+Array.from({length:9},(_,i)=>'<i style="--flag-color:'+['#e5b2b8','#e7cf96','#b5c8a2','#b0cbd1','#c7bad1'][i%5]+'"></i>').join('')+'</div><strong class="bp-stage-title">生日快乐</strong><div class="bp-cast"><div class="bp-side left">'+(ids.length?ids.slice(0,half).map(birthdayFigure).join(''):'<div class="bp-resident">'+birthdayNuomi()+'<span>糯米</span></div>')+'</div><div class="bp-player">'+birthdayCrown()+person(preset,true)+'<span>'+esc(name)+'</span></div><div class="bp-side right">'+ids.slice(half).map(birthdayFigure).join('')+'</div></div><div class="bp-cake-table">'+prop('cake','#e8b2ad')+'<i></i></div></div>';}
  function birthdayLobby(){const p=birthdayPageState(),d=birthdayStore(),ids=birthdayGuests(d),available=birthdayAvailable(d);if(p.focusFrame)cancelAnimationFrame(p.focusFrame);p.focusFrame=0;return '<section class="bp-book"><h3>今天，把甜甜的时光留给你。</h3><p class="bp-intro">'+esc(birthdayDefinition.greeting)+'</p><div class="bp-qualification"><span>示例本地日期 '+d.date+'</span><strong>'+(!available?'暂时不能入场':'生日当天 · 年度礼物已收')+'</strong></div><p class="bp-gate" role="status" tabindex="-1">'+esc(d.notice||(!available?'在生日当天收下年度小礼物后，再请朋友一起来庆祝。此页不提供领取。':ids.length?ids.length+' 位已入住朋友来庆生，糯米会先送上祝福。':birthdayDefinition.empty))+'</p><button class="primary full bp-enter" data-action="birthday-stage" '+(!available?'disabled':'')+'>'+icon('cake')+'去生日小剧场，收好祝福</button><div class="bp-lobby-cast">'+(ids.length?ids.map(birthdayFigure).join(''):'<div class="bp-resident">'+birthdayNuomi()+'<span>糯米</span></div>')+'</div><p class="bp-readonly">'+esc(available?birthdayDefinition.closing:!d.claimed?'本页示例年度生日礼物尚未收下。舞台只展示祝福，本页不提供领取。':'在生日当天且当年礼物已收后，才能进入庆生舞台；此页只展示祝福。')+'</p><details class="bp-audit"><summary>审核样本 · '+esc(birthdayAuditModes.find(([id])=>id===p.mode)?.[1]||'')+'</summary><label for="bp-mode">切换隔离状态</label><select class="settings-input" id="bp-mode">'+birthdayAuditModes.map(([id,label])=>'<option value="'+id+'" '+(p.mode===id?'selected':'')+'>'+label+'</option>').join('')+'</select><p>示例生日10月30日。只模拟当天与年度收礼资格，不修改设备时间、真实生日或领取凭据。所有来宾沿真实动物原顺序，仅展示本例已入住子集。</p><p>本页舞台打开 '+d.openCount+' 次 · 奏曲请求 '+d.songRequests+' 次。新增奖励0、回忆0、存档写入0。</p>'+btn('birthday-reset','重置当前审核样本','text-button full','rotate')+'</details><p class="bp-private">舞台只重看表演，皇冠与蛋糕只是演出道具，不进背包。正式当天与年度礼物资格由原系统判断；本页不接真实存档、日历或音频服务。</p></section>';}
  function birthdaySceneContent(){const d=birthdayStore();return '<div class="bp-scene-theatre">'+birthdayTheatre(birthdayGuests(d),d.profile.name,state.preset)+'<p>把祝福，轻轻说给你听。</p></div>';}
  function birthdayStopSound(s=activeBirthday){if(!s)return;s.timers.forEach(clearTimeout);s.timers.clear();if('speechSynthesis'in window)speechSynthesis.cancel();}
  function disposeBirthday(){if(!activeBirthday)return;const s=activeBirthday;activeBirthday=null;s.closed=true;birthdayStopSound(s);cancelAnimationFrame(s.focusFrame);s.controller.abort();s.media?.removeEventListener?.('change',s.motionChange);s.root?.replaceChildren();$('dialog').classList.remove('birthday-prototype-dialog');s.sample.notice='祝福已经收好。舞台没有增加礼物、回忆或任何奖励。';s.guests=[];}
  function birthdayValidSession(s){return !!s&&!s.closed&&activeBirthday===s&&birthdayStore()===s.sample&&s.sample.version===s.version&&birthdayAvailable(s.sample);}
