  function birthdayReport(message,s=activeBirthday){if(!s||s.closed)return;const target=s.root?.querySelector('.bp-session-status');if(target)target.textContent=message;const count=s.root?.querySelector('.bp-session-audit-count');if(count)count.textContent='本场奏曲请求 '+s.songRequests+' 次 · 本页共 '+s.sample.songRequests+' 次 · 舞台 '+s.id;}
