  let audioContext;
  function tone(index=0){try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=[261.63,293.66,329.63,349.23,392,440,493.88][index%7];gain.gain.setValueAtTime(.0001,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.10,audioContext.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.65);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.7);}catch(_){toast('当前设备没有可用音频，画面和操作仍可继续。');}}
  function speak(text){if(!('speechSynthesis'in window)){toast('当前设备没有朗读服务，可以继续阅读文字。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>/zh[-_]CN|cmn/.test(v.lang));if(voice)u.voice=voice;speechSynthesis.speak(u);}
  // 照片工作台只合成缓存底图；每个会话独立草稿、指针与绘制任务。
  let activePhotoEditor=null,photoEditorSequence=0;
  const albumBaseImages=new Map();
  const photoClamp=(value,min,max)=>Math.max(min,Math.min(max,value));
  function albumLoadBase(photo){
    if(albumBaseImages.has(photo.image))return albumBaseImages.get(photo.image);
    const pending=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>{albumBaseImages.delete(photo.image);reject(Error('照片底图暂时没有展开，请关闭后重新打开。'));};image.src=photo.image;});albumBaseImages.set(photo.image,pending);return pending;
  }
  function albumPaintSaved(root=document){
    root.querySelectorAll('canvas[data-album-photo]').forEach(canvas=>{const mode=canvas.dataset.albumMode==='review',photo=albumFind(canvas.dataset.albumPhoto);if(!photo||mode!==albumState().reviewMode)return;const saved=prototypePhotoTools.validate(photo.decor);albumLoadBase(photo).then(base=>{if(!canvas.isConnected||mode!==albumState().reviewMode)return;const ratio=photo.width/photo.height;canvas.width=canvas.classList.contains('album-composite-large')?960:360;canvas.height=Math.max(1,Math.round(canvas.width/ratio));prototypePhotoTools.draw(canvas,base,saved);canvas.setAttribute('aria-label',photo.name+'，已保存装饰');}).catch(()=>{if(canvas.isConnected){canvas.setAttribute('aria-label','照片暂时没能展开，请重新打开');canvas.classList.add('album-image-error');}});});
  }
  async function albumDownloadSaved(id,button){
    const photo=albumFind(id);if(!photo){toast('照片暂时找不到，请重新打开。');return;}const snapshot={...photo,decor:prototypePhotoTools.validate(photo.decor)};if(button)button.disabled=true;
    try{const base=await albumLoadBase(snapshot),canvas=document.createElement('canvas');canvas.width=base.naturalWidth||snapshot.width;canvas.height=base.naturalHeight||snapshot.height;prototypePhotoTools.draw(canvas,base,snapshot.decor);const image=canvas.toDataURL('image/png');if(!/^data:image\/png;base64,/.test(image))throw Error();downloadData('棉花糖小屋-原型合成照片-'+snapshot.id+'.png',image);toast('已准备原型合成PNG，包含这张照片已保存的相框、贴纸和配文。');}catch(_){toast('合成下载没有完成，请重新打开照片再试。');}finally{if(button?.isConnected)button.disabled=false;}
  }
  function disposePhotoEditor(){
    const s=activePhotoEditor;if(!s)return;s.closed=true;s.controller.abort();s.observer?.disconnect();if(s.raf)cancelAnimationFrame(s.raf);if(s.openFrame)cancelAnimationFrame(s.openFrame);s.raf=s.openFrame=0;for(const id of s.pointers.keys()){try{if(s.canvas.hasPointerCapture(id))s.canvas.releasePointerCapture(id);}catch(_){}}s.pointers.clear();s.drag=s.pinch=null;s.base=null;s.frameThumbs.clear();s.canvas.width=s.canvas.height=1;if(albumState().edit?.id===s.id)albumState().edit=null;activePhotoEditor=null;$('dialog').classList.remove('photo-workbench-dialog');
  }
