      const d=loginGiftState(),s=loginGiftStore(),reward=loginGiftStatus().reward;if(d.mode==='coinCap')s.coin=loginModel.config.maxCoin-reward.coin;else if(d.mode==='seedCap')Object.keys(loginModel.config.seeds).forEach(id=>{if((s.seeds[id]||0)+loginModel.config.seeds[id]>9999)s.seeds[id]=9999-loginModel.config.seeds[id];});else if(d.mode==='itemCap'&&reward.itemId)s.inventory[reward.itemId]=9998;else return;s.notice='审核样本已腾出所需空间，领取日期、累计次数和原定礼物没有改变。';s.error=false;render();return;
