    if(cmd==='festival-calendar'){modal('小岛一整年的好日子','<p class="dialog-intro">当前游戏按季节、日期与生日呈现祝福和限定礼物。以下为日历样式示意。</p>'+[['flower','春日花信','樱花、小种子与第一次开花'],['sun','夏日小聚','晴天、海风与傍晚的彩虹'],['leaf','秋日收获','落叶、果实与南瓜色的小灯'],['gift','冬日心意','雪花、暖窗与节日来信']].map(x=>task(x[0],x[1],x[2],'festival-gift')).join(''));return;}
    if(cmd==='festival-gift'){detail('送给当日的一点小祝福','正式游戏按节日年份记录限定礼物，重看不会再次领取。原型只演示祝福与礼物展示。','gift');return;}
