    if(cmd==='bake-next'){if(state.bakeStep<2){state.bakeStep++;scene.addObject('cake');render();toast(state.bakeStep===1?'水果备好啦，开始搅拌奶油。':'软软的奶油铺好啦，摆上喜欢的水果。');}else{state.bakeStep=3;render();detail('这份'+state.bakeFruit+'蛋糕，做好啦',state.bakeCoop?'你放了水果，桃桃加了奶油，布丁做了装饰。每个人都留了一点快乐在里面。':'花园的收获变成了高级蛋糕。可以在小屋摆放，或送给喜欢甜品的居民。','cake',state.bakeCoop?'finish-game':'overview-go:residents',state.bakeCoop?'看看大家的纪念奖励':'送给小动物朋友');}return;}
