    if(cmd==='link-account'){modal('第一次遇见，这三份选择','<p class="dialog-intro">请选择真正想继续的小屋。正式游戏不会自动用一个孩子的小屋覆盖另一个孩子的进度。</p>'+task('home','关联这台设备的小屋','把当前进度存到自己的账号','account-option:关联当前小屋')+task('cloud','恢复账号里的小屋','先看清云端进度，再继续','account-option:恢复云端小屋')+task('plus','给空账号建一座新小屋','保留本机副本，不混合进度','account-option:为空账号新建'));return;}
